window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"rB3FB3o4vfk","speaker":"Faustin Archange Touadera","role":"Head of State","country":"Central African Republic","region":"Africa","url":"https://www.youtube.com/watch?v=rB3FB3o4vfk","date":"20260923","title":"🇨🇫 Central African Republic - Head of State Addresses United Nations General Debate, 81st Session","seconds":925,"words":1610,"counts":{"claims":28,"promises":0,"attacks":0},"topics":[{"topic":"UN Security Council","share":0.1647,"seconds":152},{"topic":"Central African Republic conflict","share":0.1528,"seconds":141},{"topic":"Central African Republic security","share":0.1468,"seconds":136},{"topic":"Climate finance","share":0.0752,"seconds":70},{"topic":"Humanitarian funding","share":0.0724,"seconds":67},{"topic":"Sudan conflict","share":0.0702,"seconds":65},{"topic":"AI governance","share":0.0697,"seconds":64},{"topic":"Central African Republic economy","share":0.0689,"seconds":64},{"topic":"Global conflicts","share":0.0681,"seconds":63},{"topic":"Colonial reparations","share":0.0669,"seconds":62},{"topic":"UN collective action","share":0.0445,"seconds":41}],"timeline":[[8,83,"Central African Republic security"],[84,147,"Global conflicts"],[150,220,"UN Security Council"],[221,288,"Humanitarian funding"],[289,363,"Central African Republic conflict"],[365,431,"Central African Republic conflict"],[433,503,"Climate finance"],[504,568,"Central African Republic economy"],[570,634,"Sudan conflict"],[636,696,"Central African Republic security"],[697,780,"UN Security Council"],[783,847,"AI governance"],[848,910,"Colonial reparations"],[913,955,"UN collective action"]],"stances":{"Central African Republic security":"Faustin Archange Touadera states he is speaking on behalf of the Central African Republic with a sense of responsibility and pride, emphasizing the need to restore trust and manage transformation.","Global conflicts":"Faustin Archange Touadera states that global conflicts are multiplying, fueling one another, and causing severe humanitarian and economic disruptions.","UN Security Council":"Faustin Archange Touadera states that divisions within the UN Security Council are paralyzing necessary action and that international law is being dismissed as optional, causing suffering for vulnerable populations.","Humanitarian funding":"Faustin Archange Touadera states that humanitarian funding and official development aid have declined to critical levels, forcing peacekeeping operations to reduce activities and arguing that budget cuts in capitals enable armed groups by preventing necessary development.","Central African Republic conflict":"Faustin Archange Touadera argues that abandoning fragile countries is counterproductive and that peace must be built through dialogue, justice, and shared development rather than force.","Climate finance":"Faustin Archange Touadera demands full operationalization of the loss and damage fund, equitable adaptation financing, and just compensation for Congo basin countries.","Central African Republic economy":"Faustin Archange Touadera states that the national development plan 2024-2028 serves as a renewed social contract focused on five pillars to restore trust between the state and citizens.","Sudan conflict":"Faustin Archange Touadera states that the war in neighboring Sudan has caused significant refugee movements and resource pressures on the Central African Republic.","AI governance":"Faustin Archange Touadera argues that developing countries must have decision-making power over AI governance rather than merely being users, and calls for a global digital compact to ensure affordable connectivity and skills transfer.","Colonial reparations":"Faustin Archange Touadera argues that colonial reparations are a necessary demand for future justice and supports the African Union's prioritization of this issue.","UN collective action":"Faustin Archange Touadera calls for the UN to move from taking stock to taking action, emphasizing that saving the world is a collective responsibility."},"claims":[{"t":50,"quote":"I take the floor on behalf of the Central African Republic with the full sense of responsibility bestowed by this podium and the pride of a people that has never given up hope.","topic":"Central African Republic security","kind":"self_credit"},{"t":96,"quote":"On all continents, conflicts are multiplying, becoming and fueling one another.","topic":"Global conflicts","kind":"fact"},{"t":116,"quote":"They're costing civilian lives, destroying schools and hospitals, and displacing entire families.","topic":"Global conflicts","kind":"fact"},{"t":128,"quote":"Disruptions around the trade of Hormuz are causing energy and fertilizer prices to skyrocket.","topic":"Global conflicts","kind":"fact"},{"t":135,"quote":"Migration, forced migration routes are growing crowded. Terrorism, trafficking, and armed groups are flourishing in zones beyond state control.","topic":"Global conflicts","kind":"fact"},{"t":207,"quote":"According to the UN itself, more than 147 million people in 19 countries and territories experienced acute food insecurity caused by conflict in 2025.","topic":"UN Security Council","kind":"number"},{"t":230,"quote":"humanitarian funding has fallen to its lowest levels since 2016","topic":"Humanitarian funding","kind":"number"},{"t":236,"quote":"Official development aid is crumbling","topic":"Humanitarian funding","kind":"fact"},{"t":240,"quote":"Peacekeeping operations, including in my own country, have been forced to cut back their patrols, shut down bases, and suspend local dialogue","topic":"Humanitarian funding","kind":"fact"},{"t":297,"quote":"abandoning fragile countries will not lead to It's simply putting off a bill that will have to be paid with interest.","topic":"Central African Republic conflict","kind":"fact"},{"t":324,"quote":"Peace cannot be decreed. It must be built day after day through dialogue, justice, and shared development.","topic":"Central African Republic conflict","kind":"fact"},{"t":373,"quote":"Out of the 14 armed groups that signed the political agreement for peace and reconciliation, 11 have already voluntarily disbanded as part of the disarmament, demobilization, reintegration, and repatriation program.","topic":"Central African Republic conflict","kind":"number"},{"t":390,"quote":"The last two groups involved in this process are continuing the process of disbandment in accordance with the Jamina Accord.","topic":"Central African Republic conflict","kind":"fact"},{"t":453,"quote":"My country will bring three demands to the 31st conference of the parties in Antalya, Turkey.","topic":"Climate finance","kind":"fact"},{"t":475,"quote":"the countries of the Congo basin, the second largest lung of the planet, should finally be justly compensated","topic":"Climate finance","kind":"fact"},{"t":518,"quote":"This is the goal of our national development plan 2024 2028 which has five pillars. Security and human capital, resilient infrastructure, economic production and environmental These pillars are not only a planning framework but are also a renewed social contract with our population.","topic":"Central African Republic economy","kind":"fact"},{"t":559,"quote":"A well-trained and employed youth involved in decision-making is the best guarantee against recruitment by armed groups.","topic":"Central African Republic economy","kind":"fact"},{"t":594,"quote":"The war in neighboring Sudan has pushed more than 27,000 refugees to settle around the city of Bir alone.","topic":"Sudan conflict","kind":"number"},{"t":603,"quote":"population of Purau has more than doubled, exerting intolerable pressure on water resources and on already strained services.","topic":"Sudan conflict","kind":"fact"},{"t":613,"quote":"The town of Amdafuk last June experienced an escalation of violence that put more than 11,000 of our compatriots on the street.","topic":"Sudan conflict","kind":"number"},{"t":640,"quote":"My country with its legendary hospitality is not complaining.","topic":"Central African Republic security","kind":"fact"},{"t":651,"quote":"The C like all sovereign nations aspires to take full charge of its own","topic":"Central African Republic security","kind":"fact"},{"t":712,"quote":"A continent of more than 1.3 billion whose crises make up a large portion of the council's work, ought to have at least one permanent seat in it.","topic":"UN Security Council","kind":"fact"},{"t":730,"quote":"two years after its adoption, negotiations on security council reform are still ongoing.","topic":"UN Security Council","kind":"fact"},{"t":808,"quote":"digital transformation and the rise of artificial intelligence are rightly considered to be one of the great promises of our time.","topic":"AI governance","kind":"fact"},{"t":848,"quote":"The wounds left behind by colonization are still being felt in our continent.","topic":"Colonial reparations","kind":"fact"},{"t":875,"quote":"The African Union has prioritized this and the C fully supports these efforts.","topic":"Colonial reparations","kind":"fact"},{"t":922,"quote":"Saving the world is not a task for one nation or one continent. It is our collective will to action.","topic":"UN collective action","kind":"fact"}],"promises":[],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":8,"topic":"Central African Republic security","text":"The assembly will now hear an address by his excellency Fan Alon Tuadora, head of state of the Central African Republic. I request protocol to escort his excellency and invite him to address the assembly. President of the General Assembly, distinguished secretary general, excellencies, ladies and gentlemen, I take the floor on behalf of the Central African Republic with the full sense of responsibility bestowed by this podium and the pride of a people that has never given up hope. Mr. President, this session is taking place at the time of a two-fold need to restore trust and to manage transformation to understand the urgent need for action."},{"t":84,"topic":"Global conflicts","text":"Let us gaze upon the world as it is first. It has been a long time since peace has seemed so fragile. On all continents, conflicts are multiplying, becoming and fueling one another. Each has its reasons, its history, its but they all have one thing in common. They're costing civilian lives, destroying schools and hospitals, and displacing entire families. These crises never remain contained. Disruptions around the trade of Hormuz are causing energy and fertilizer prices to skyrocket. Migration, forced migration routes are growing crowded. Terrorism, trafficking, and armed groups are flourishing in zones beyond state control."},{"t":150,"topic":"UN Security Council","text":"However far they may be from the front line, no state is safe from the repercussions of these conflicts. At the same time, divisions within the Security the body charged with protecting international peace and security, are paralyzing action where it is the most urgently needed. International law is supposed to protect the weak from the ambitions of the powerful. Yet, it is increasingly being dismissed as optional. This is the paradox of our time. We have never had so many reasons to act together and we have never found it so difficult to do so. This paradox comes with a price and this price is primarily being paid by the most vulnerable. According to the UN itself, more than 147 million people in 19 countries and territories experienced acute food insecurity caused by conflict in 2025."},{"t":221,"topic":"Humanitarian funding","text":"And yet at the time at a time when need is soaring, resources are shrinking, humanitarian funding has fallen to its lowest levels since 2016. Official development aid is crumbling. Peacekeeping operations, including in my own country, have been forced to cut back their patrols, shut down bases, and suspend local dialogue Each budget cut adopted in New York or in some faraway capital is an opportunity for armed groups on the The trap is an insidious one. A fragile country needs security to develop. It needs development for stability. When health care, education, roads, energy, and youth employment are placed on the back burner, it is not only the SGS that move out of reach."},{"t":289,"topic":"Central African Republic conflict","text":"It is peace itself that is jeopardized. I'd like to emphasize that abandoning fragile countries will not lead to It's simply putting off a bill that will have to be paid with interest. The C understands this trap and it also knows how to escape it. It has undergone trials that remain fresh in our memory &gt;&gt; and has learned a lesson. Peace cannot be decreed. It must be built day after day through dialogue, justice, and shared development. No peace imposed by force can be Only a negotiated peace that is just and inclusive can truly restore trust between nations. That is why we made the difficult and often criticized choice of an inclusive political dialogue, negotiated disarmament and national instead of a military response alone."},{"t":365,"topic":"Central African Republic conflict","text":"This olive branch policy has led to tangible results that I'd like to share with this assembly. Out of the 14 armed groups that signed the political agreement for peace and reconciliation, 11 have already voluntarily disbanded as part of the disarmament, demobilization, reintegration, and repatriation program. The last two groups involved in this process are continuing the process of disbandment in accordance with the Jamina Accord. I say this with the conviction of lived experience. Holding out one's hand to yesterday's opponent is not a sign of weakness. It is often the safest path toward a lasting peace. And that is why I renew the proposal that the C has been making for several sessions now to establish a global conflict prevention and mediation mechanism with predictable financing and that is managed with complete transparency."},{"t":433,"topic":"Climate finance","text":"Mr. President, we cannot restore trust without tackling climate change with the same resolve. There cannot be lasting security without climate security. There cannot be climate security without climate My country will bring three demands to the 31st conference of the parties in Antalya, Turkey. that the loss and damage fund become fully operational and accessible, that adaptation financing should no longer be the forgotten stepchild of climate finance, and that the countries of the Congo basin, the second largest lung of the planet, should finally be justly compensated for the services they provide to humanity by protecting their ecosystems. This demand for justice also applies to global health. We call for equitable equitable access to vaccines and healthcare technologies and for strengthening health systems in the most vulnerable countries."},{"t":504,"topic":"Central African Republic economy","text":"Restoring trust, Mr. President, is not limited to interstate relations. First and foremost, it is built within our own borders between the state and its citizens. This is the goal of our national development plan 2024 2028 which has five pillars. Security and human capital, resilient infrastructure, economic production and environmental These pillars are not only a planning framework but are also a renewed social contract with our population. At the heart of this ambition lies our Our youth is our greatest asset, our greatest responsibility. A well-trained and employed youth involved in decision-making is the best guarantee against recruitment by armed groups."},{"t":570,"topic":"Sudan conflict","text":"The same is true for women whose role in peace building is not a bonus but a prerequisite. Mr. President, my country, like so many others, is experiencing the impact of crises surrounding it. From refugee movements to pressure on our borders, pressure on our borders. The war in neighboring Sudan has pushed more than 27,000 refugees to settle around the city of Bir alone. population of Purau has more than doubled, exerting intolerable pressure on water resources and on already strained services. The town of Amdafuk last June experienced an escalation of violence that put more than 11,000 of our compatriots on the street. While the arrival of Sudanese livestock firm farmers fleeing with their flocks has inflamed new tensions with our rural populations over access to water and land."},{"t":636,"topic":"Central African Republic security","text":"Tensions that armed groups eagerly exploit. My country with its legendary hospitality is not complaining. We are asking for regional international solidarity to be commenurate with the challenges we're facing. The C like all sovereign nations aspires to take full charge of its own And I say this with the same gravity. Any draw down of Minutusa ought to be gradual based upon objective and agreed criteria and not be based on an arbitrary timeline untethered from realities on the ground. Mr. President, the transformation that is the theme of this session is what we want. But we refuse to allow it to take place without Africa or while exploiting Africa."},{"t":697,"topic":"UN Security Council","text":"This transformation first requires a bold security council reform. We cannot claim to represent the world of 2026 with the proportions of A continent of more than 1.3 billion whose crises make up a large portion of the council's work, ought to have at least one permanent seat in it. The pact for the future has opened a window, but two years after its adoption, negotiations on security council reform are still ongoing. The decision so urgently needed has yet to be made. The African position represented for years now by the Esawini consensus and the cert declaration is not a favor we're asking. It is a demand for justice and effectiveness. next requires peacekeeping operations with realistic mandates and predictable We support strengthening the UN African Union partnership including through predictable financing for African-led operations."},{"t":783,"topic":"AI governance","text":"Lastly, the transformation requires an international financial architecture that stops penalizing fragile countries. These reforms are not favors. They are investments in the world stability. The UN must benefit all of its members. Mr. President, digital transformation and the rise of artificial intelligence are rightly considered to be one of the great promises of our time. The global digital compact must become a reality. affordable connectivity, skills transfer, data protection and a governance of AI in which developing countries decide instead of simply being users. The transformation requires facing history with lucidity."},{"t":848,"topic":"Colonial reparations","text":"The wounds left behind by colonization are still being felt in our continent. Reparations are not simply reopening of feud of the past. They are demand for justice for the future, recognition of the wrongs committed, restitution of cultural goods and archives, equitable cooperation, debt relief. There are many possible paths. The African Union has prioritized this and the C fully supports these efforts. calls for real respect for the sovereignty of states. Sanctions and restrictions must be tools for peace and must be adjusted in accordance with the progress made. They must not be retaliatory measures serving geopolitical interests. Mr. President, we are at a crossroads. We have our diagnosis."},{"t":913,"topic":"UN collective action","text":"It is now time for decision. That is why the C calls upon the UN to Saving the world is not a task for one nation or one continent. It is our collective will to action. Let this 81st session be one in which we stop taking stock and begin taking Thank you for your kind attention. &gt;&gt; On behalf of the assembly, I wish to thank the head of state of the Central African Republic"}],"compare":[{"topic":"UN & its reform","share":0.2092,"mean":0.2047,"rank":86,"others":170},{"topic":"Democratic Republic of the Congo","share":0.1528,"mean":0.0042,"rank":3,"others":6},{"topic":"Central African Republic","share":0.1468,"mean":0.0,"rank":1,"others":0},{"topic":"Climate Change","share":0.0752,"mean":0.0426,"rank":48,"others":77},{"topic":"Humanitarian Aid","share":0.0724,"mean":0.0015,"rank":3,"others":5},{"topic":"Sudan","share":0.0702,"mean":0.0069,"rank":8,"others":15},{"topic":"Artificial Intelligence","share":0.0697,"mean":0.0504,"rank":60,"others":83},{"topic":"International Law & Order","share":0.0681,"mean":0.0604,"rank":68,"others":102}]};
